create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,message text not null,type text not null default 'info',is_read boolean not null default false,created_at timestamptz not null default now()); create index if not exists notifications_user_created_idx on public.notifications(user_id,created_at desc); alter table public.notifications enable row level security;